import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Development troubleshooting","description":"Diagnose local Ershu development problems by installation, connection, queue, index, and browser symptoms.","frontmatter":{"page_id":"development-troubleshooting","description":"Diagnose local Ershu development problems by installation, connection, queue, index, and browser symptoms."},"headers":[],"relativePath":"en/development/troubleshooting.md","filePath":"en/development/troubleshooting.md","lastUpdated":1786627803000}'),s={name:"en/development/troubleshooting.md"};function r(i,e,l,c,d,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="development-troubleshooting" tabindex="-1">Development troubleshooting <a class="header-anchor" href="#development-troubleshooting" aria-label="Permalink to &quot;Development troubleshooting&quot;">​</a></h1><p>When troubleshooting Ershu, first identify the layer where progress stops: dependency installation, infrastructure, API, Worker, frontend, or the output of one run. A successful liveness check does not prove that the complete analysis path works.</p><h2 id="uv-sync-cannot-fetch-an-ershu-package" tabindex="-1"><code>uv sync</code> cannot fetch an Ershu package <a class="header-anchor" href="#uv-sync-cannot-fetch-an-ershu-package" aria-label="Permalink to &quot;`uv sync` cannot fetch an Ershu package&quot;">​</a></h2><p><strong>Typical symptom:</strong> Installation reports that an Ershu component version is missing, <code>uv.lock</code> is absent, or the Python package index cannot be reached.</p><p><strong>Common cause:</strong> The directory is not from a published tag, component publishing is still in progress, the lock file changed, or the network proxy cannot reach the package index.</p><p><strong>Action:</strong></p><ol><li>Confirm that the deployment directory came from a published tag or Release archive.</li><li>Confirm that <code>uv.lock</code> exists and has no local changes.</li><li>Check whether the component version in the error is available from the configured index.</li><li>Check the proxy, certificate, and package-index settings used by UV.</li></ol><p><strong>Recovery evidence:</strong> <code>uv sync --locked --extra all</code> finishes without rewriting the lock file. Skipping one component is not a successful composition install.</p><h2 id="frontend-dependency-installation-or-startup-fails" tabindex="-1">Frontend dependency installation or startup fails <a class="header-anchor" href="#frontend-dependency-installation-or-startup-fails" aria-label="Permalink to &quot;Frontend dependency installation or startup fails&quot;">​</a></h2><p>Check the version first:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The frontend is fixed to Node.js 24. The version should start with <code>v24</code>, and <code>npm ci</code> should exit with code <code>0</code>. Do not hide a version mismatch by updating the lockfile.</p><p>If <code>npm run dev</code> starts but the page is blank, inspect both the browser console and the build error in the terminal. After correction, <code>http://localhost:3000</code> should enter setup, sign-in, or a project page.</p><h2 id="the-frontend-reports-a-network-error-or-keeps-loading" tabindex="-1">The frontend reports a network error or keeps loading <a class="header-anchor" href="#the-frontend-reports-a-network-error-or-keeps-loading" aria-label="Permalink to &quot;The frontend reports a network error or keeps loading&quot;">​</a></h2><p>Check the API directly:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8000/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>No connection means the API is not running, uses another port, or is blocked by a local network rule.</li><li>A response with status <code>ok</code> means the API process is alive; continue with the frontend proxy.</li></ul><p>In development, the frontend proxies <code>/api</code> to <code>http://localhost:8000</code> by default. If the API runs elsewhere, change <code>VITE_DEV_API_PROXY</code> in <code>.env.local</code> and restart <code>npm run dev</code>.</p><p><strong>Recovery evidence:</strong> The frontend root enters initial administrator setup, sign-in, or the project list according to database state and no longer reports repeated request failures.</p><h2 id="health-works-but-project-operations-fail" tabindex="-1"><code>/health</code> works but project operations fail <a class="header-anchor" href="#health-works-but-project-operations-fail" aria-label="Permalink to &quot;`/health` works but project operations fail&quot;">​</a></h2><p><code>/health</code> and <code>/api/v1/health</code> only report API liveness. Use the dependency endpoint for a wider check:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8000/api/v1/health/dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This response checks the database and Milvus and reports <code>ok</code> or <code>degraded</code>. It does not check Redis. An <code>ok</code> response therefore does not prove that login rate limiting, queue-related connections, or the Worker are healthy.</p><p><strong>Action:</strong> Use the <code>database</code> and <code>milvus</code> fields to check addresses, credentials, and service state. Inspect Redis and the Worker separately.</p><h2 id="a-run-remains-queued" tabindex="-1">A run remains <code>queued</code> <a class="header-anchor" href="#a-run-remains-queued" aria-label="Permalink to &quot;A run remains `queued`&quot;">​</a></h2><p><strong>Most likely cause:</strong> The Worker is not running, or the Worker and API connect to different databases.</p><p><strong>Check in order:</strong></p><ol><li>Confirm that <code>uv run ershu-worker</code> is still running.</li><li>Confirm that the API and Worker use the same database, Redis, Milvus, and related key settings.</li><li>Inspect the current Worker error, especially repository credentials, branch selection, and model channels.</li><li>Correct the cause before deciding to cancel or retry. Do not create repeated identical runs.</li></ol><p><strong>Recovery evidence:</strong> The run moves from <code>queued</code> to <code>scanning</code>, <code>analyzing</code>, or <code>finalizing</code>, and the detail page gains new timeline content.</p><h2 id="the-first-run-does-not-allow-repository-or-incremental-scope" tabindex="-1">The first run does not allow repository or incremental scope <a class="header-anchor" href="#the-first-run-does-not-allow-repository-or-incremental-scope" aria-label="Permalink to &quot;The first run does not allow repository or incremental scope&quot;">​</a></h2><p>This is an expected restriction, not a frontend failure. A project must first establish a full-project baseline that covers every active repository.</p><p>Select <strong>Full project</strong> (<code>full_project</code>) and keep all active repositories in scope. After the baseline completes, the capability response may enable repository or incremental runs. Always use the options returned for the current project.</p><p><strong>Recovery evidence:</strong> The first full-project run can be submitted and appears in the run list.</p><h2 id="a-run-fails-because-of-model-configuration" tabindex="-1">A run fails because of model configuration <a class="header-anchor" href="#a-run-fails-because-of-model-configuration" aria-label="Permalink to &quot;A run fails because of model configuration&quot;">​</a></h2><p>Repository analysis requires a usable LLM channel. Model names, API keys, and endpoints do not come from <code>.env</code>.</p><p>On the administrator model channels page, confirm that:</p><ul><li>at least one <code>llm</code> channel is enabled;</li><li>its connection or model test works;</li><li>the project or run selects a valid channel; and</li><li>HTTPS is used when submitting a secret through a non-localhost name.</li></ul><p><strong>Recovery evidence:</strong> A new run no longer fails immediately for lack of an LLM channel and advances into scanning or analysis.</p><h2 id="semantic-search-is-unavailable-or-hybrid-search-is-degraded" tabindex="-1">Semantic search is unavailable or hybrid search is degraded <a class="header-anchor" href="#semantic-search-is-unavailable-or-hybrid-search-is-degraded" aria-label="Permalink to &quot;Semantic search is unavailable or hybrid search is degraded&quot;">​</a></h2><p>Inspect <code>search_index_status</code> on the latest run:</p><ul><li><code>indexed</code> means the semantic index was built;</li><li><code>degraded</code> means part of the capability is unavailable and its warning needs attention; and</li><li><code>unavailable</code> means there is no usable semantic index.</li></ul><p>Semantic mode does not silently pretend to be keyword search. Hybrid mode can explicitly fall back to keyword results and shows a degradation notice.</p><p><strong>Action:</strong> Confirm that a separate enabled embedding channel exists, that the run selected it, and that the run warnings and Milvus dependency state are clear.</p><p><strong>Recovery evidence:</strong> After a new full analysis builds the index, a semantic query returns results without an unresolved degradation reason.</p><h2 id="docs-is-empty-or-chat-has-no-context" tabindex="-1">Docs is empty or chat has no context <a class="header-anchor" href="#docs-is-empty-or-chat-has-no-context" aria-label="Permalink to &quot;Docs is empty or chat has no context&quot;">​</a></h2><p>Check in order:</p><ol><li>Is the latest run <code>completed</code> or <code>completed_with_warnings</code>?</li><li>Does the run detail actually list generated documents?</li><li>For a run with warnings, did a repository or document stage fail?</li><li>Is chat open in the intended project?</li><li>Does the project have a usable model channel and searchable content?</li></ol><p>Chat on Docs is always project-scoped. It does not automatically narrow itself to the current document or section, so citations from another repository are not necessarily a scope error.</p><p><strong>Recovery evidence:</strong> Docs opens a generated document, and citations in a chat answer open the corresponding source preview.</p><h2 id="authenticated-writes-are-rejected-by-csrf-or-transport-policy" tabindex="-1">Authenticated writes are rejected by CSRF or transport policy <a class="header-anchor" href="#authenticated-writes-are-rejected-by-csrf-or-transport-policy" aria-label="Permalink to &quot;Authenticated writes are rejected by CSRF or transport policy&quot;">​</a></h2><p>For local development, prefer <code>localhost</code> or <code>127.0.0.1</code>. Production and any other hostname require HTTPS.</p><p>When HTTPS terminates at a reverse proxy, check that:</p><ul><li>the external Host and Origin are preserved;</li><li><code>X-Forwarded-Proto</code> contains the real external scheme;</li><li>the API trusts the actual proxy source; and</li><li>cookie and allowed-origin settings match the external address.</li></ul><p>Do not disable CSRF or secure cookies to make a request pass.</p><p><strong>Recovery evidence:</strong> Sign-in restores a session, and cookie-authenticated writes such as project creation or model-channel changes are no longer classified as cross-site or insecure.</p><h2 id="an-mcp-client-connects-to-the-wrong-port" tabindex="-1">An MCP client connects to the wrong port <a class="header-anchor" href="#an-mcp-client-connects-to-the-wrong-port" aria-label="Permalink to &quot;An MCP client connects to the wrong port&quot;">​</a></h2><p>In a same-origin deployment, <code>/api/</code> must reach the API on port 8000, while <code>/mcp/</code> must reach MCP on port 8001. Do not send <code>/mcp/</code> to the API or accidentally remove the MCP path prefix in the proxy.</p><p><strong>Recovery evidence:</strong> The web API remains usable, and the MCP client can establish its separate connection through <code>/mcp/</code>.</p><h2 id="a-completed-run-no-longer-receives-live-events" tabindex="-1">A completed run no longer receives live events <a class="header-anchor" href="#a-completed-run-no-longer-receives-live-events" aria-label="Permalink to &quot;A completed run no longer receives live events&quot;">​</a></h2><p>This is expected. An active run uses a snapshot and events after its cursor. <code>completed</code> and <code>completed_with_warnings</code> load the final result directly and no longer connect to the event stream. <code>failed</code> and <code>cancelled</code> also receive no further live events.</p><p><strong>Recovery evidence:</strong> Refreshing a completed run immediately shows its final text, analysis blocks, warnings, and documents instead of replaying early output.</p><h2 id="frontend-checks-fail" tabindex="-1">Frontend checks fail <a class="header-anchor" href="#frontend-checks-fail" aria-label="Permalink to &quot;Frontend checks fail&quot;">​</a></h2><p>Treat each command separately:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>For a test failure, correct the state logic or request contract instead of deleting the assertion.</li><li><code>lint</code> includes both code rules and TypeScript checks.</li><li>For a formatting failure, reformat only the files in your change so unrelated work is not overwritten.</li><li>For a build failure, start with the first build error instead of the last line.</li></ul><p>Automated checking is complete only when all four commands exit with code <code>0</code> and the build creates <code>dist/</code>. Chinese and English routes, themes, narrow screens, and long-run refresh still need browser checks. See <a href="./frontend">frontend development</a> for the full change procedure.</p>',66)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
